import { test, expect } from '@playwright/test';

test.describe('Table Column Freezing on Horizontal Scroll', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should freeze the first column when scrolling horizontally', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify first column header is visible
    const firstColumnHeader = page.getByText('ID');
    await expect(firstColumnHeader).toBeVisible();

    // Verify first column data cell is visible
    const firstDataCell = page.getByText('1');
    await expect(firstDataCell).toBeVisible();

    // Scroll horizontally to trigger column freeze
    const scrollContainer = page.locator('[data-testid="table-scroll-container"]');
    await scrollContainer.evaluate((el) => {
      el.scrollBy({ left: 1000 });
    });

    // Verify first column remains visible and frozen
    await expect(firstColumnHeader).toBeVisible();
    await expect(firstDataCell).toBeVisible();

    // Verify other columns are visible and scrollable
    const secondColumnHeader = page.getByText('Name');
    await expect(secondColumnHeader).toBeVisible();

    const thirdColumnHeader = page.getByText('Email');
    await expect(thirdColumnHeader).toBeVisible();

    // Verify first column data is still visible after scrolling
    const frozenData = page.getByText('1');
    await expect(frozenData).toBeVisible();
  });

  test('should not freeze first column when scrolling vertically', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify first column header is visible
    const firstColumnHeader = page.getByText('ID');
    await expect(firstColumnHeader).toBeVisible();

    // Verify first column data cell is visible
    const firstDataCell = page.getByText('1');
    await expect(firstDataCell).toBeVisible();

    // Scroll vertically to trigger row scrolling
    const scrollContainer = page.locator('[data-testid="table-scroll-container"]');
    await scrollContainer.evaluate((el) => {
      el.scrollBy({ top: 1000 });
    });

    // Verify first column is not frozen (i. Scroll should be possible)
    const firstRowData = page.getByText('1');
    await expect(firstRowData).toBeVisible();

    // Verify first column header is still visible
    await expect(firstColumnHeader).toBeVisible();

    // Verify other columns are visible
    const secondColumnHeader = page.getByText('Name');
    await expect(secondColumnHeader).toBeVisible();

    // Verify first column data is still visible after vertical scroll
    await expect(firstDataCell).toBeVisible();
  });
});
